/**
 * Renders `src/styles/tokens.css` from the token source. The CSS selects the theme from
 * prefers-color-scheme unless `data-theme` on <html> overrides it, applies dyslexia mode from
 * `data-reading="dyslexia"`, and leaves motion handling to base.css.
 */
import {
  COLOUR_TOKENS,
  colours,
  dyslexiaLightPaper,
  dyslexiaReading,
  fonts,
  lineHeights,
  motion,
  radii,
  shadowRaised,
  typeScale,
  type ColourToken,
  type Mode,
} from "./tokens";

const HEADER =
  "/* Generated by packages/ui/scripts/generate-tokens-css.ts from src/tokens/tokens.ts. Do not edit. */";

function block(selector: string, declarations: string[], indent = ""): string {
  const inner = declarations.map((line) => `${indent}  ${line}`).join("\n");
  return `${indent}${selector} {\n${inner}\n${indent}}`;
}

function nested(atRule: string, inner: string): string {
  return `${atRule} {\n${inner}\n}`;
}

function colourDeclarations(mode: Mode, overrides: Partial<Record<ColourToken, string>> = {}) {
  return [
    `color-scheme: ${mode};`,
    ...COLOUR_TOKENS.map((token) => `--${token}: ${overrides[token] ?? colours[mode][token]};`),
  ];
}

export function renderTokensCss(): string {
  const shared = [
    `--font-display-family: ${fonts.display};`,
    `--font-body-family: ${fonts.body};`,
    `--font-annotation-family: ${fonts.annotation};`,
    `--font-mono-family: ${fonts.mono};`,
    ...Object.entries(typeScale).map(([name, value]) => `--type-${name}: ${value};`),
    `--line-height-body: ${lineHeights.body};`,
    `--line-height-display: ${lineHeights.display};`,
    `--reading-letter-spacing: normal;`,
    `--reading-word-spacing: normal;`,
    `--reading-line-height: ${lineHeights.body};`,
    ...Object.entries(radii).map(([name, value]) => `--radius-${name}-size: ${value};`),
    `--shadow-raised-value: ${shadowRaised};`,
    `--duration-micro: ${motion.micro};`,
    `--duration-standard: ${motion.standard};`,
    `--duration-panel: ${motion.panel};`,
    `--ease-standard-curve: ${motion.easeStandard};`,
    `--ease-exit-curve: ${motion.easeExit};`,
    `--duration-reduced-cross-fade: ${motion.reducedCrossFade};`,
  ];
  const dyslexia = [
    `--font-body-family: ${fonts.dyslexic};`,
    `--reading-letter-spacing: ${dyslexiaReading.letterSpacing};`,
    `--reading-word-spacing: ${dyslexiaReading.wordSpacing};`,
    `--reading-line-height: ${dyslexiaReading.lineHeight};`,
  ];
  const cream = colourDeclarations("light", dyslexiaLightPaper);

  const sections = [
    HEADER,
    block(":root", [...colourDeclarations("light"), ...shared]),
    nested(
      "@media (prefers-color-scheme: dark)",
      block(':root:not([data-theme="light"])', colourDeclarations("dark"), "  "),
    ),
    block(':root[data-theme="dark"]', colourDeclarations("dark")),
    block(':root[data-reading="dyslexia"]', dyslexia),
    block(':root[data-reading="dyslexia"][data-theme="light"]', cream),
    nested(
      "@media (prefers-color-scheme: light)",
      block(':root[data-reading="dyslexia"]:not([data-theme="dark"])', cream, "  "),
    ),
  ];
  return `${sections.join("\n\n")}\n`;
}
